function rampartSimulate(createStrategy, seed, maxTicks, rec) {
  "use strict";
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  function makeRoute(pts) {
    var segs = [], total = 0;
    for (var i = 0; i + 1 < pts.length; i++) {
      var x0 = pts[i][0] * 100 + 50, y0 = pts[i][1] * 100 + 50;
      var x1 = pts[i + 1][0] * 100 + 50, y1 = pts[i + 1][1] * 100 + 50;
      var len = Math.abs(x1 - x0) + Math.abs(y1 - y0);
      segs.push({ x0: x0, y0: y0, ux: Math.sign(x1 - x0), uy: Math.sign(y1 - y0), start: total, len: len });
      total += len;
    }
    return { segs: segs, len: total };
  }
  var ROUTES = [
    makeRoute([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]),
    makeRoute([[0, 6], [21, 6], [21, 11], [23, 11]])
  ];
  var SLOTS = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var TNAMES = ["bolt", "cannon", "frost", "lance", "flak"];
  var TUR = [
    { cost: 50, dmg: 26, period: 8, range: 300, splash: 0, slow: 0, pierce: 0, ground: 1, air: 1 },
    { cost: 90, dmg: 60, period: 24, range: 260, splash: 90, slow: 0, pierce: 0, ground: 1, air: 0 },
    { cost: 70, dmg: 10, period: 12, range: 240, splash: 0, slow: 30, pierce: 0, ground: 1, air: 1 },
    { cost: 120, dmg: 180, period: 36, range: 360, splash: 0, slow: 0, pierce: 1, ground: 1, air: 0 },
    { cost: 80, dmg: 40, period: 10, range: 320, splash: 70, slow: 0, pierce: 0, ground: 0, air: 1 }
  ];
  var ENAMES = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
  var EN = [
    { hp: 60, speed: 10, bounty: 4, leak: 1, air: 0, first: 1, weight: 10 },
    { hp: 40, speed: 20, bounty: 4, leak: 1, air: 0, first: 2, weight: 4 },
    { hp: 50, speed: 12, bounty: 6, leak: 2, air: 1, first: 3, weight: 3 },
    { hp: 150, speed: 6, bounty: 9, leak: 3, air: 0, first: 4, weight: 3 },
    { hp: 90, speed: 8, bounty: 6, leak: 2, air: 0, first: 6, weight: 2 },
    { hp: 70, speed: 8, bounty: 7, leak: 2, air: 0, first: 8, weight: 1 },
    { hp: 0, speed: 12, bounty: 1, leak: 1, air: 0, first: 1e9, weight: 0 }
  ];
  function tierDamage(ti, tier) {
    var d = TUR[ti].dmg;
    for (var k = 1; k < tier; k++) d = Math.floor(d * 16 / 10);
    return d;
  }
  var rng = mulberry32(seed);
  var mult = [0, 1000];
  function hpMult(w) {
    while (mult.length <= w) mult.push(Math.floor(mult[mult.length - 1] * 108 / 100));
    return mult[w];
  }
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), out = [], sum = 0, i, k;
    for (k = 0; k < 6; k++) if (EN[k].first <= w) sum += EN[k].weight;
    for (i = 0; i < n; i++) {
      var r = rng() % sum;
      for (k = 0; k < 6; k++) {
        if (EN[k].first > w) continue;
        if (r < EN[k].weight) break;
        r -= EN[k].weight;
      }
      out.push(k);
    }
    return out;
  }
  function place(e) {
    var route = ROUTES[e.air], segs = route.segs, p = e.progress, i = segs.length - 1;
    while (i > 0 && segs[i].start > p) i--;
    var s = segs[i], d = p - s.start;
    e.x = s.x0 + s.ux * d; e.y = s.y0 + s.uy * d;
  }
  function view(e) {
    return { id: e.id, type: ENAMES[e.type], hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor,
      speed: e.speed, slowed: e.slow > 0 ? 1 : 0, remaining: ROUTES[e.air].len - e.progress };
  }

  var strategy = createStrategy();
  var hasTarget = !!strategy && typeof strategy.target === "function";
  var log = [];
  var gold = 250, baseHp = 10, wave = 0, nextId = 1, fallTick = -1;
  var turrets = [];
  for (var si = 0; si < 16; si++) turrets.push(null);
  var enemies = [];
  var pending = [];
  var nextComp = genWave(1);
  var G = { tick: 0, wave: 0, gold: gold, baseHp: baseHp, turrets: turrets, enemies: enemies, nextWave: nextComp, fell: false, names: ENAMES };

  function spawn(type, w, progress, maxHp) {
    var d = EN[type];
    var e = { id: nextId++, type: type, wave: w, hp: maxHp, maxHp: maxHp, progress: progress, air: d.air, speed: d.speed,
      armor: type === 0 ? Math.floor(w / 4) : (type === 3 ? 6 + w : 0), slow: 0, age: 0, x: 0, y: 0 };
    place(e);
    enemies.push(e);
    return e;
  }
  function applyActions(tick, actions) {
    if (!Array.isArray(actions)) return;
    var n = Math.min(actions.length, 32);
    for (var i = 0; i < n; i++) {
      var a = actions[i];
      if (!a || typeof a !== "object") continue;
      var slot = a.slot;
      if (typeof slot !== "number" || slot !== Math.floor(slot) || slot < 0 || slot > 15) continue;
      var t = turrets[slot];
      if (a.op === "build") {
        var ti = TNAMES.indexOf(a.type);
        if (ti < 0 || t || gold < TUR[ti].cost) continue;
        gold -= TUR[ti].cost;
        turrets[slot] = { slot: slot, type: ti, tier: 1, spent: TUR[ti].cost, cd: 0, x: SLOTS[slot][0] * 100 + 50, y: SLOTS[slot][1] * 100 + 50,
          dmg: TUR[ti].dmg, range: TUR[ti].range };
        log.push([tick, "B", slot, ti]);
        if (rec) rec("B", tick, slot, ti);
      } else if (a.op === "upgrade") {
        if (!t || t.tier >= 3) continue;
        var cost = TUR[t.type].cost * t.tier;
        if (gold < cost) continue;
        gold -= cost; t.spent += cost; t.tier++;
        t.dmg = tierDamage(t.type, t.tier); t.range = TUR[t.type].range + 30 * (t.tier - 1);
        log.push([tick, "U", slot, t.tier]);
        if (rec) rec("U", tick, slot, t.tier);
      } else if (a.op === "sell") {
        if (!t) continue;
        gold += Math.floor(t.spent * 70 / 100);
        turrets[slot] = null;
        log.push([tick, "S", slot, 0]);
        if (rec) rec("S", tick, slot, t.type);
      }
    }
  }

  var endTick = maxTicks;
  for (var tick = 0; tick < maxTicks; tick++) {
    var i, j, e;
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      var comp = nextComp;
      nextComp = genWave(wave + 1);
      var st = { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: [], enemies: [], nextWave: [] };
      for (i = 0; i < 16; i++) {
        var tt = turrets[i];
        st.slots.push({ slot: i, x: SLOTS[i][0] * 100 + 50, y: SLOTS[i][1] * 100 + 50,
          turret: tt ? { type: TNAMES[tt.type], tier: tt.tier, spent: tt.spent } : null });
      }
      for (i = 0; i < enemies.length; i++) st.enemies.push(view(enemies[i]));
      for (i = 0; i < nextComp.length; i++) st.nextWave.push(ENAMES[nextComp[i]]);
      applyActions(tick, strategy.plan(st));
      pending.push({ wave: wave, comp: comp, start: tick, idx: 0 });
      if (rec) rec("W", tick, wave);
    }
    // 2. spawn
    for (i = 0; i < pending.length; i++) {
      var pw = pending[i];
      if (pw.idx < pw.comp.length && pw.start + 4 * pw.idx === tick) {
        var ty = pw.comp[pw.idx++];
        spawn(ty, pw.wave, 0, Math.floor(EN[ty].hp * hpMult(pw.wave) / 1000));
      }
    }
    while (pending.length && pending[0].idx >= pending[0].comp.length) pending.shift();
    // 3. move
    var fell = false, w = 0;
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      e.progress += e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      if (e.progress >= ROUTES[e.air].len) {
        baseHp -= EN[e.type].leak;
        log.push([tick, "L", e.id, baseHp]);
        if (rec) rec("L", tick, e, baseHp);
        if (baseHp <= 0) { fell = true; break; }
      } else {
        place(e);
        enemies[w++] = e;
      }
    }
    if (fell) {
      log.push([tick, "F", wave, 0]);
      fallTick = tick; endTick = tick;
      if (rec) { G.tick = tick; G.wave = wave; G.gold = gold; G.baseHp = baseHp; G.nextWave = nextComp; G.fell = true; rec("F", tick, G); }
      break;
    }
    enemies.length = w;
    // 4. age & heal
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      e.age++;
      if (e.type === 5 && e.age % 20 === 0) {
        for (j = 0; j < enemies.length; j++) {
          var o = enemies[j], hx = o.x - e.x, hy = o.y - e.y;
          if (hx * hx + hy * hy <= 22500) o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100));
        }
        if (rec) rec("H", tick, e);
      }
    }
    // 5. turrets fire
    for (var s = 0; s < 16; s++) {
      var t = turrets[s];
      if (!t) continue;
      if (t.cd > 0) { t.cd--; if (t.cd > 0) continue; }
      var def = TUR[t.type], r2 = t.range * t.range, best = null, cands = hasTarget ? [] : null, dx, dy;
      for (i = 0; i < enemies.length; i++) {
        e = enemies[i];
        if (e.hp <= 0) continue;
        if (e.air ? !def.air : !def.ground) continue;
        dx = e.x - t.x; dy = e.y - t.y;
        if (dx * dx + dy * dy > r2) continue;
        if (best === null || e.progress - ROUTES[e.air].len > best.progress - ROUTES[best.air].len) best = e;
        if (cands) cands.push(e);
      }
      if (best === null) continue;
      if (cands) {
        var views = [];
        for (i = 0; i < cands.length; i++) views.push(view(cands[i]));
        var pick = strategy.target({ slot: s, type: TNAMES[t.type], tier: t.tier, x: t.x, y: t.y, range: t.range }, views);
        for (i = 0; i < cands.length; i++) if (cands[i].id === pick) { best = cands[i]; break; }
      }
      var killed = false, px = best.x, py = best.y;
      if (def.splash > 0) {
        var sr2 = def.splash * def.splash;
        for (i = 0; i < enemies.length; i++) {
          e = enemies[i];
          if (e.hp <= 0) continue;
          if (e.air ? !def.air : !def.ground) continue;
          dx = e.x - px; dy = e.y - py;
          if (dx * dx + dy * dy > sr2) continue;
          e.hp -= def.pierce ? t.dmg : Math.max(1, t.dmg - e.armor);
          if (def.slow > 0) e.slow = def.slow;
          if (e.hp <= 0) killed = true;
        }
      } else {
        best.hp -= def.pierce ? t.dmg : Math.max(1, t.dmg - best.armor);
        if (def.slow > 0) best.slow = def.slow;
        if (best.hp <= 0) killed = true;
      }
      t.cd = def.period;
      if (rec) rec("X", tick, t, best, px, py);
      if (killed) {
        var n0 = enemies.length; w = 0;
        var born = [];
        for (i = 0; i < n0; i++) {
          e = enemies[i];
          if (e.hp > 0) { enemies[w++] = e; continue; }
          log.push([tick, "K", e.id, s]);
          gold += EN[e.type].bounty;
          if (rec) rec("K", tick, e, s);
          if (e.type === 4) born.push(e);
        }
        enemies.length = w;
        for (i = 0; i < born.length; i++) {
          var sp = born[i], shp = Math.max(1, Math.floor(sp.maxHp / 4));
          for (j = 0; j < 3; j++) { var c = spawn(6, sp.wave, sp.progress, shp); if (rec) rec("P", tick, c, sp); }
        }
      }
    }
    // 6. slow timers
    for (i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow--;
    if (rec) { G.tick = tick; G.wave = wave; G.gold = gold; G.baseHp = baseHp; G.nextWave = nextComp; rec("T", tick, G); }
  }

  var str = JSON.stringify(log), h = 0x811c9dc5;
  for (var q = 0; q < str.length; q++) { h ^= str.charCodeAt(q); h = Math.imul(h, 0x01000193); }
  var hash = ("0000000" + (h >>> 0).toString(16)).slice(-8);
  return { score: Math.round((endTick - 20) / 40 * 100) / 100, fallTick: fallTick, log: log, hash: hash };
}

