// targeting experiments
var TDMG = { bolt: [26, 41, 65], cannon: [60, 96, 153], frost: [10, 16, 25], lance: [180, 288, 460], flak: [40, 64, 102] };
var TSPL = { bolt: 0, cannon: 90, frost: 0, lance: 0, flak: 70 };
var P = { wR: 1, wB: 1, wW: 1, killBonus: 0, remW: 0 };
function makeTF(P) {
  return function (t, c) {
    var n = c.length, i, j;
    if (n === 1) return c[0].id;
    var dmg = TDMG[t.type][t.tier - 1], spl = TSPL[t.type];
    if (spl > 0) {
      var s2 = spl * spl, best = -1, bv = -1, val = new Array(n);
      for (i = 0; i < n; i++) {
        var e = c[i], d = dmg - e.armor; if (d < 1) d = 1;
        var v = e.hp < d ? e.hp + P.killBonus * e.maxHp : d;
        if (e.type === "runner") v *= P.wR; else if (e.type === "brute") v *= P.wB;
        val[i] = v * (1 + P.remW * (4600 - e.remaining) / 4600);
      }
      for (i = 0; i < n; i++) {
        var a = c[i], sum = 0;
        for (j = 0; j < n; j++) { var b = c[j], dx = a.x - b.x, dy = a.y - b.y; if (dx * dx + dy * dy <= s2) sum += val[j]; }
        if (sum > bv || (sum === bv && a.remaining < c[best].remaining)) { bv = sum; best = i; }
      }
      return c[best].id;
    }
    return -1;
  };
}

