// build-list strategy factory (dev). list: array of [slot, typeChar]; nth appearance of a slot = build / upgrade / upgrade
load("lib.js"); load("tf1.js");
var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
function listStrategy(list, tf, reserveFn) {
  return function () {
    var ptr = 0;
    var o = { plan: function (s) {
      var a = [], g = s.gold, tiers = [], i;
      for (i = 0; i < 16; i++) tiers.push(s.slots[i].turret ? s.slots[i].turret.tier : 0);
      var reserve = reserveFn ? reserveFn(s) : 0;
      while (ptr < list.length && a.length < 32) {
        var it = list[ptr], sl = it[0], ty = TCH[it[1]], c = COST[ty] * (tiers[sl] === 0 ? 1 : tiers[sl]);
        if (g - c < reserve) break;
        a.push(tiers[sl] === 0 ? { op: "build", slot: sl, type: ty } : { op: "upgrade", slot: sl });
        tiers[sl]++; g -= c; ptr++;
      }
      return a; } };
    if (tf) o.target = tf;
    return o;
  };
}
function orderToList(layout, order) { // order: array of slots (each 3 times)
  return order.map(function (s) { return [s, layout[s]]; });
}

