load("lib.js");
var STRATFILE = (typeof STRATFILE !== "undefined") ? STRATFILE : "strat.js";
load(STRATFILE);
var args = arguments;
var STRAT_PARAMS = args[0] ? JSON.parse(args[0]) : {};
var ns = args[1] ? parseInt(args[1]) : 12, verbose = args[2] | 0;
var seeds = []; for (var i = 0; i < ns; i++) seeds.push(101 + i * 7);
var t0 = preciseTime(), res = [], worst = 0;
for (var i = 0; i < seeds.length; i++) {
  var t1 = preciseTime();
  var leaks = [], gold = [];
  var r = rampartSimulate(createStrategy, seeds[i], 12020, verbose ? function (kind, tick, a, b) {
    if (kind === "L") leaks.push(((tick - 20) / 40 + 1).toFixed(1) + ":" + ["G", "R", "W", "B", "S", "M", "s"][a.type] + a.wave);
    if (kind === "T" && (tick - 20) % 200 === 0) gold.push(a.wave + ":" + a.gold);
  } : undefined);
  var dt = preciseTime() - t1; if (dt > worst) worst = dt;
  res.push(r.score);
