#!/usr/bin/env python3
"""Parallel config evaluation. usage: par.py NSEEDS [--strat file] 'json1' 'json2' ...  (or --file configs.txt)"""
import subprocess, sys, json, re, os
from concurrent.futures import ThreadPoolExecutor
JSC = "/System/Library/Frameworks/JavaScriptCore.framework/Versions/Current/Helpers/jsc"
HERE = os.path.dirname(os.path.abspath(__file__))

def run_one(cfg, nseeds, strat="strat.js", seed0=101, step=7):
    cmd = [JSC, "-e", "var STRATFILE=%s; var SEED0=%d; var SEEDSTEP=%d;" % (json.dumps(strat), seed0, step), "run.js", "--", cfg, str(nseeds)]
    out = subprocess.run(cmd, cwd=HERE, capture_output=True, text=True).stdout.strip().split("\n")[-1]
    m = re.search(r"mean ([\d.]+) min ([\d.]+) max ([\d.]+) time ([\d.]+) worst ([\d.]+)", out)
    if not m:
        return (cfg, -1, 0, 0, 0, out)
    return (cfg, float(m.group(1)), float(m.group(2)), float(m.group(3)), float(m.group(5)), "")

def evaluate(cfgs, nseeds, strat="strat.js", workers=9, seed0=101, step=7):
    with ThreadPoolExecutor(workers) as ex:
        return list(ex.map(lambda c: run_one(c, nseeds, strat, seed0, step), cfgs))

if __name__ == "__main__":
    args = sys.argv[1:]
    n = int(args.pop(0))
    strat = "strat.js"; seed0 = 101
    while args and args[0].startswith("--"):
        if args[0] == "--strat": strat = args[1]; args = args[2:]
        elif args[0] == "--seed0": seed0 = int(args[1]); args = args[2:]
        elif args[0] == "--file": args = [l.strip() for l in open(args[1]) if l.strip()] + args[2:]
    res = evaluate(args, n, strat, seed0=seed0)
    for r in sorted(res, key=lambda r: -r[1]):
        print("%.2f  min %.2f max %.2f  worst-time %.2f  %s %s" % (r[1], r[2], r[3], r[4], r[0], r[5]))

