#!/usr/bin/env python3
"""Coordinate descent on the slot type layout under real play. usage: climb.py NSEEDS START_TYPES 'base json' [alts]"""
import sys, json
from par import evaluate
n = int(sys.argv[1]); cur = list(sys.argv[2]); base = json.loads(sys.argv[3]) if len(sys.argv) > 3 else {}
alts = sys.argv[4] if len(sys.argv) > 4 else "cklb"
strat = sys.argv[5] if len(sys.argv) > 5 else "strat.js"
def cfg(types):
    d = dict(base); d["types"] = "".join(types); return json.dumps(d)
best = evaluate([cfg(cur)], n, strat)[0][1]
print("start", "".join(cur), best, flush=True)
improved = True
while improved:
    improved = False
    for s in range(16):
        cands = []
        for a in alts:
            if a != cur[s]:
                t = list(cur); t[s] = a; cands.append(t)
        res = evaluate([cfg(t) for t in cands], n, strat)
        bi = max(range(len(res)), key=lambda i: res[i][1])
        print("  slot", s, " ".join("%s:%.2f" % (cands[i][s], res[i][1]) for i in range(len(res))), flush=True)
        if res[bi][1] > best + 0.02:
            best = res[bi][1]; cur = cands[bi]; improved = True
            print("improved", "".join(cur), best, flush=True)
print("final", "".join(cur), best, flush=True)

