import Cocoa
import WebKit

// usage: snap <file.html> <out.png> <width> <height> <waitSeconds> [js-to-run-after-load] [waitAfterJs]
let args = CommandLine.arguments
let fileURL = URL(fileURLWithPath: args[1])
let outPath = args[2]
let W = CGFloat(Double(args[3]) ?? 1280), H = CGFloat(Double(args[4]) ?? 650)
let wait = Double(args[5]) ?? 2.0
let js = args.count > 6 ? args[6] : ""
let wait2 = args.count > 7 ? (Double(args[7]) ?? 0.5) : 0.5

class Handler: NSObject, WKNavigationDelegate, WKScriptMessageHandler {
    var web: WKWebView!
    func userContentController(_ c: WKUserContentController, didReceive message: WKScriptMessage) {
        print("[page] \(message.body)")
    }
    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
        DispatchQueue.main.asyncAfter(deadline: .now() + wait) {
            webView.evaluateJavaScript(js.isEmpty ? "0" : js) { res, err in
                if let e = err { print("[js error] \(e)") }
                if let r = res { print("[js result] \(r)") }
                DispatchQueue.main.asyncAfter(deadline: .now() + wait2) {
                    let cfg = WKSnapshotConfiguration()
                    webView.takeSnapshot(with: cfg) { img, err in
                        if let img = img, let tiff = img.tiffRepresentation, let rep = NSBitmapImageRep(data: tiff), let png = rep.representation(using: .png, properties: [:]) {
                            try? png.write(to: URL(fileURLWithPath: outPath))
                            print("[snap] wrote \(outPath) \(rep.pixelsWide)x\(rep.pixelsHigh)")
                        } else { print("[snap] failed \(String(describing: err))") }
                        exit(0)
                    }
                }
            }
        }
    }
    func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) { print("[nav fail] \(error)"); exit(2) }
    func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: Error) { print("[nav fail] \(error)"); exit(2) }
}

let app = NSApplication.shared
app.setActivationPolicy(.accessory)
let config = WKWebViewConfiguration()
let handler = Handler()
let hook = """
(function(){ function send(k, a){ try { window.webkit.messageHandlers.log.postMessage(k + ': ' + Array.prototype.map.call(a, function(x){ return (x && x.stack) ? x.stack : String(x); }).join(' ')); } catch(e){} }
['log','warn','error'].forEach(function(k){ var o = console[k]; console[k] = function(){ send(k, arguments); o.apply(console, arguments); }; });
window.addEventListener('error', function(e){ send('onerror', [e.message + ' @' + e.lineno + ':' + e.colno]); }); })();
"""
config.userContentController.addUserScript(WKUserScript(source: hook, injectionTime: .atDocumentStart, forMainFrameOnly: true))
config.userContentController.add(handler, name: "log")
config.preferences.setValue(true, forKey: "allowFileAccessFromFileURLs")
let web = WKWebView(frame: NSRect(x: 0, y: 0, width: W, height: H), configuration: config)
web.navigationDelegate = handler
handler.web = web
let window = NSWindow(contentRect: NSRect(x: 0, y: 0, width: W, height: H), styleMask: [.borderless], backing: .buffered, defer: false)
window.contentView = web
window.orderFrontRegardless()
web.loadFileURL(fileURL, allowingReadAccessTo: fileURL.deletingLastPathComponent())
DispatchQueue.main.asyncAfter(deadline: .now() + 60) { print("[timeout]"); exit(3) }
app.run()

