// injected test driver: exercises the playback state machine through the public controls only
(function () {
  var L = window.__sm = [], $ = function (id) { return document.getElementById(id); };
  function snap(tag) {
    var c = $("countdown"), cs = getComputedStyle(c);
    L.push(tag + " | cd=" + cs.display + ":'" + c.textContent + "' scrub=" + $("scrubber").value + " aria=" + $("btn-toggle").getAttribute("aria-label") +
      " pause=" + (getComputedStyle($("icon-pause")).display) + " play=" + (getComputedStyle($("icon-play")).display) +
      " pills=" + Array.prototype.map.call(document.querySelectorAll(".speed-pill"), function (p) { return (p.classList.contains("is-active") ? "A" : "-") + p.getAttribute("aria-checked")[0]; }).join(""));
  }
  var steps = [
    [300, function () { snap("countdown@0.3 (expect 3)"); }],
    [1400, function () { snap("countdown@1.4 (expect 2)"); }],
    [2500, function () { snap("countdown@2.5 (expect 1)"); }],
    [3600, function () { snap("playing@3.6 (expect hidden, scrub~0.5)"); }],
    [3700, function () { $("btn-toggle").click(); snap("after pause click"); }],
    [4200, function () { snap("still paused (same scrub)"); $("btn-toggle").click(); snap("after resume click"); }],
    [4700, function () { snap("playing again"); document.querySelectorAll(".speed-pill")[3].click(); snap("speed 2x clicked"); }],
    [5700, function () { snap("1s at 2x (scrub should gain ~2)"); $("btn-refire").click(); snap("after refire click (expect 0, hidden, Pause)"); }],
    [6500, function () { snap("refire hold@0.8 (expect still 0, hidden)"); }],
    [7000, function () { snap("after hold (expect playing, 2x kept)"); }],
    [7100, function () { var s = $("scrubber"); s.value = "99.5"; s.dispatchEvent(new Event("input")); snap("scrubbed to 99.5 (expect paused)"); }],
    [7300, function () { $("btn-toggle").click(); }],
    [8000, function () { snap("ended (expect 100.000, Play)"); $("btn-toggle").click(); snap("toggle from ended (expect 0, Pause)"); }],
    [8500, function () { snap("playing from 0 after ended"); $("btn-refire").click(); }],
    [8700, function () { $("btn-toggle").click(); snap("toggle during refire hold (expect paused at 0)"); }],
    [9300, function () { snap("still paused at 0"); L.push("DONE"); }]
  ];
  steps.forEach(function (st) { setTimeout(st[1], st[0]); });
})();

